package local.lito381.server;

import java.io.IOException;
import java.net.InetAddress;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.net.ssl.SSLServerSocket;
import javax.net.ssl.SSLSocket;

/**
 * Test-only true TLS + source/selection authority + actual backend commit permit.
 * No DB/disk writes and no fabricated navigation success. Busy is generated by
 * the production navigation while its true operation holder remains admitted.
 */
public final class ModernEquipmentBusyTestPeer {
    private ModernEquipmentBusyTestPeer() {}
    public static void main(String[] args) throws Exception {
        if (args.length != 4 || !args[0].equals("serve") || !Set.of("back-busy", "back-busy-wrong-phase",
                "back-busy-wrong-selected").contains(args[2])) throw new IllegalArgumentException("invalid equipment test peer invocation");
        int lifetime = Integer.parseInt(args[3]);
        if (lifetime < 1000 || lifetime > 30_000) throw new IllegalArgumentException("bounded test peer lifetime required");
        var context = ModernTlsTestMaterial.serverContext(Path.of(args[1]),false);
        var fixture = new ModernApplicationTestBackend("auth");
        var data = new ModernCharacterDataTestFixtures(false);
        var presence = new TournamentPresence();
        var backend = new ModernBackendExecutor(1,1);
        var callers = Executors.newSingleThreadExecutor();
        var watchdog = Executors.newSingleThreadScheduledExecutor();
        var watchdogFired = new AtomicBoolean();
        int busyReplies = 0;
        try (backend; var listener = (SSLServerSocket)context.getServerSocketFactory().createServerSocket(
                0,1,InetAddress.getByAddress(new byte[]{127,0,0,1}))) {
            listener.setSoTimeout(5000); System.out.println("READY " + listener.getLocalPort()); System.out.flush();
            try (var socket = (SSLSocket)listener.accept(); var transport = new ModernTlsSessionTransport(socket,
                    ModernSessionBoundary.Policy.current(),new ModernTlsSessionTransport.Limits(2000,2000),fixture.verifier);
                 var gate = backend.openSession()) {
                transport.attachBackend(gate,2000);
                var navigation = new ModernNavigationSession(transport,fixture.characters,gate,2000,presence);
                var stop = watchdog.schedule(() -> { watchdogFired.set(true); transport.failClosed(); },lifetime,TimeUnit.MILLISECONDS);
                try {
                    var negotiated = transport.negotiate();
                    navigation.negotiateRecords(negotiated.version() >= 5);
                    int previous = negotiated.requestId();
                    boolean offered = false, awaitingRetry = false;
                    for (;;) {
                        try (var message = transport.readApplication(3000)) {
                            if (message == null) break;
                            if (Integer.compareUnsigned(message.requestId(),previous)<=0) throw new IOException("fixture request order");
                            previous=message.requestId();
                            if (message instanceof ModernApplicationProtocol.Ping ping) {
                                transport.writeApplication(new ModernApplicationProtocol.Pong(ping.requestId()));
                            } else if (message instanceof ModernApplicationProtocol.RecordRequest request) {
                                transport.writeApplication(navigation.record(request));
                            } else if (message instanceof ModernApplicationProtocol.Auth auth) {
                                var principal = transport.authenticateForApplication(auth.account(),auth.password());
                                var sources = principal.sources().stream().sorted(Comparator.comparingInt(ModernAccountAuthentication.Source::id))
                                        .map(source -> new ModernApplicationProtocol.Source(source.id(),source.name())).toList();
                                transport.writeApplication(new ModernApplicationProtocol.AuthResult(auth.requestId(),0,principal.account(),sources));
                            } else if (message instanceof ModernApplicationProtocol.CharacterRequest request) {
                                if (awaitingRetry) throw new IOException("client reloaded roster after busy BACK");
                                navigation.beforeCharacterRequest();
                                var principal = transport.authenticatedPrincipal().orElseThrow();
                                var rows = gate.call(2000,scope -> fixture.characters.characters(principal,request.sourceId()));
                                transport.writeApplication(new ModernApplicationProtocol.CharacterResult(request.requestId(),request.sourceId(),request.selectionEpoch(),0,rows));
                                navigation.recordRoster(request.sourceId(),request.selectionEpoch(),rows);
                            } else if (message instanceof ModernApplicationProtocol.CharacterDataRequest request) {
                                transport.writeApplication(navigation.characterData(request,data));
                            } else if (message instanceof ModernApplicationProtocol.CharacterReturn request && !offered) {
                                var admitted = new CountDownLatch(1); var release = new CountDownLatch(1);
                                var held = callers.submit(() -> navigation.equipment(request.sourceId(),request.objectId(),request.selectionEpoch(),
                                        (principal,character,operation) -> {
                                            if(!operation.tryCommit()) throw new IOException("test commit permit unavailable");
                                            admitted.countDown();
                                            if(!release.await(1800,TimeUnit.MILLISECONDS)) throw new IOException("test permit release timeout");
                                            return 1;
                                        }));
                                try {
                                    if(!admitted.await(1500,TimeUnit.MILLISECONDS)) throw new IOException("test permit admission timeout");
                                    var reply = navigation.handle(request);
                                    if(reply.status()!=3 || reply.phase()==0) throw new IOException("production BACK did not preserve busy selection");
                                    if(args[2].equals("back-busy-wrong-phase")) {
                                        int phase = reply.phase()==1 ? 2 : 1;
                                        reply = new ModernApplicationProtocol.NavigationResult(reply.requestId(),reply.action(),3,phase,
                                                phase==1?255:0,reply.sourceId(),reply.objectId(),reply.selectionEpoch(),reply.selected(),reply.channels());
                                    } else if(args[2].equals("back-busy-wrong-selected")) {
                                        var row = reply.selected();
                                        reply = new ModernApplicationProtocol.NavigationResult(reply.requestId(),reply.action(),3,reply.phase(),
                                                reply.channelId(),reply.sourceId(),reply.objectId(),reply.selectionEpoch(),
                                                new ModernApplicationProtocol.CharacterRow(row.objectId(),row.name()+" changed",row.characterClass(),row.sex(),row.level()),reply.channels());
                                    }
                                    transport.writeApplication(reply); busyReplies++; offered=true; awaitingRetry=true;
                                } finally { release.countDown(); held.get(2500,TimeUnit.MILLISECONDS); }
                            } else {
                                var reply = navigation.handle(message);
                                if(reply.status()!=0) throw new IOException("fixture expected accepted navigation");
                                if(message instanceof ModernApplicationProtocol.CharacterSelection) offered=false;
                                if(message instanceof ModernApplicationProtocol.CharacterReturn) awaitingRetry=false;
                                transport.writeApplication(reply);
                            }
                        } catch (IOException closedAfterCorruptReply) {
                            if(!args[2].equals("back-busy") && busyReplies>0 && transport.state()==ModernTlsSessionTransport.State.CLOSED) break;
                            throw closedAfterCorruptReply;
                        }
                    }
                } finally { stop.cancel(false); transport.close(); }
            }
        } finally {
            callers.shutdown(); watchdog.shutdownNow(); backend.close();
            if(!callers.awaitTermination(3000,TimeUnit.MILLISECONDS) || !watchdog.awaitTermination(1000,TimeUnit.MILLISECONDS)
                    || !backend.awaitTermination(3000)) throw new IOException("equipment test peer workers did not retire");
            if(presence.ownerCount()!=0 || presence.userCount()!=0) throw new IOException("equipment test peer selection leaked");
        }
        if(watchdogFired.get() || busyReplies==0) throw new IOException("equipment test peer did not exercise bounded busy BACK");
    }
}
